insert into public.network_specs (network, label, formats, copy_max_chars, length_group, notes, source_url, verified_on, updated_at) select network, label, formats, copy_max_chars, length_group, notes, source_url, verified_on, updated_at from jsonb_populate_record(null::public.network_specs, '{"label": "X", "notes": "El largo se cuenta con twitter-text (links = 23, emojis = 2). Cuentas Premium aceptan más.", "formats": {"video": {"max_fps": 60, "max_width": 1920, "max_height": 1200, "max_size_mb": 512, "audio_codecs": ["aac"], "video_codecs": ["avc", "h264"], "max_duration_s": 140, "min_duration_s": 0.5}}, "network": "x", "source_url": "https://developer.x.com/en/docs/x-api/v1/media/upload-media/uploading-media/media-best-practices", "updated_at": "2026-10-26T07:40:36.406253+00:00", "verified_on": null, "length_group": "short", "copy_max_chars": 280}'::jsonb);
insert into public.network_specs (network, label, formats, copy_max_chars, length_group, notes, source_url, verified_on, updated_at) select network, label, formats, copy_max_chars, length_group, notes, source_url, verified_on, updated_at from jsonb_populate_record(null::public.network_specs, '{"label": "YouTube", "notes": "Shorts hasta 3 min en vertical o cuadrado. Título máx. 100 caracteres.", "formats": {"short": {"aspects": ["9:16", "1:1"], "max_fps": 60, "max_duration_s": 180, "aspect_tolerance": 0.02}, "video": {"max_fps": 60, "max_size_mb": 262144, "max_duration_s": 43200}}, "network": "youtube", "source_url": "https://support.google.com/youtube/answer/15424877", "updated_at": "2026-10-26T07:40:36.406253+00:00", "verified_on": null, "length_group": "long", "copy_max_chars": 5000}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "a1d90480-d4fa-467c-81f1-88173ab16610", "key": "guia:agenda-privada", "body": "La fecha, la hora, la dirección exacta, cómo llegar y los contactos de cada evento son información de seguridad. Solo los ven el jefe, Despacho, Administración y quien graba (solo sus eventos asignados). Redes, Supervisión y Secretaría nunca los ven; Redes ve solo el día cuando el evento ya pasó. Lo impide la base de datos, no solo la pantalla. El asistente no tiene la agenda y nunca la da: el que la necesite y tenga permiso la ve en la Agenda. Tampoco se escribe en avisos ni correos.", "tags": ["agenda", "seguridad", "fecha", "hora", "direccion"], "roles": null, "title": "La agenda del jefe es privada", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "46162e00-faf1-458c-8ca6-b24e73985569", "key": "guia:ajustes", "body": "Ajustes (solo Administración): Equipo, Categorías, Fórmulas de copies, Horarios de tweets y mejores horas, Reglas de video por red, Marca (textos, saludo, cierres y hashtags), Buzón (todos los correos que generó la plataforma; con datos de prueba no sale ninguno), Registro de cambios (quién hizo qué) y el Asistente (lo que sabe, cómo contesta y su nombre). «Ver como…» muestra los menús de otro rol para revisar, sin cambiar permisos.", "tags": ["ajustes", "configuracion"], "roles": ["admin"], "title": "Qué se cambia en Ajustes", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "f64aae25-e8b7-4d67-9308-221aaa501c04", "key": "guia:asignar-grabacion", "body": "En la ficha del evento, en «Quién graba», se elige a la persona; también al crear el evento. A esa persona le llega un aviso (y un correo). Para cambiarla, se quita y se asigna otra. Asignan Despacho, Redes y Administración.", "tags": ["grabacion", "asignar"], "roles": ["dispatch", "admin", "social"], "title": "Cómo se asigna quién graba", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "34fe03c1-a67a-4b45-bfd6-ae508b42882c", "key": "guia:asistente-panel", "body": "En Ajustes → Asistente, Administración ve lo que sabe el asistente (fichas), cómo contesta (guiones, con un probador que no gasta turnos), las conversaciones, cómo va (respuestas degradadas, errores, tiempos), lo que pregunta la gente, lo que dejó por confirmar, lo que hizo (con deshacer) y su nombre, cara y presentación. Las fichas automáticas avisan antes de editarse: si se editan, pasan a ser del equipo y ya no se actualizan solas.", "tags": ["asistente", "panel"], "roles": ["admin"], "title": "El panel del asistente", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "58b01290-3005-4a0e-8ff3-f0644cec634d", "key": "guia:avisos", "body": "La campana de arriba muestra tus avisos: asignaciones, cambios pedidos, piezas por aprobar, plazos vencidos, tweets que se acaban. Tocar un aviso abre lo que corresponde; nunca aprueba nada por sí solo. «Marcar todo como leído» los limpia. Las preferencias de correo están en Mi perfil. Ningún aviso lleva fecha, hora ni lugar de un evento.", "tags": ["avisos", "notificaciones", "campana"], "roles": null, "title": "Los avisos", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "ad1d4dcd-182a-4729-8e2b-398a0f6ecb88", "key": "guia:calificar-eventos", "body": "En Política (desde Inicio) el jefe ve los eventos que esperan su decisión: los califica de 1 a 10 y los acepta o rechaza. También se puede desde la ficha del evento. Solo el jefe decide; Despacho no puede hacerlo en su nombre.", "tags": ["politica", "eventos", "decidir", "propuestas", "aceptar", "rechazar", "calificar"], "roles": ["boss", "admin", "dispatch", "secretary"], "title": "Calificar, aceptar o rechazar eventos", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "ceb96bc3-272f-40d6-b472-de42ffec947c", "key": "guia:cambiar-evento", "body": "Despacho y Administración cambian el título, el lugar, la fecha y la ficha técnica desde la ficha del evento. No hay botón para duplicar un evento: se crea otro en «Crear» → Nuevo evento. Tampoco hay botón para cancelarlo ni para borrarlo: si un evento ya no conviene, el jefe lo rechaza en Política o en su ficha, y si hay que quitarlo, Despacho le avisa a Administración. Secretaría no cambia una propuesta ya enviada: le avisa a Despacho.", "tags": ["cambiar", "cancelar", "duplicar", "borrar", "suspender", "editar"], "roles": ["dispatch", "admin", "boss", "secretary"], "title": "Cambiar, cancelar o duplicar un evento", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "a12b94d9-aa8d-4824-9219-4e6b142305e7", "key": "guia:como-aprobar", "body": "En Por aprobar las piezas salen agrupadas por color, con el video, los tres copies y el historial. Las verdes se aprueban todas juntas, de una vez, con el botón «Aprobar las…» del grupo verde (las que cambiaron mientras tanto se saltan). Antes de aprobar una pieza sola, se revisa con la lista: cifras con fuente, sin fecha ni hora, se ve y se oye bien, copies revisados. Si trae un error o algo no va, se piden cambios con un comentario, anotando el segundo del video si hace falta. Una pieza delicada se puede subir a rojo; también se puede «Pedir frase al jefe». Los tweets se aprueban marcándolos en su pestaña.", "tags": ["aprobar", "supervision", "lista", "revisar", "chequeo", "cambios", "error", "verde", "amarillo"], "roles": ["supervisor", "admin", "boss"], "title": "Cómo aprueba Supervisión y qué revisar antes", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "9d21bdcb-655e-4cc3-9a8f-800c62704b95", "key": "guia:como-aprobar-rojo", "body": "Las piezas en rojo las aprueba solo el jefe; supervisión puede pedir cambios. En Inicio, en el recuadro «Te toca aprobar», o en Por aprobar: abrir la pieza, ver el video y los copies, marcar la lista de chequeo y tocar Aprobar. Si algo no va, pedir cambios con un comentario (se puede anotar el segundo del video). Si no responde, la pieza no sale.", "tags": ["aprobar", "rojo", "jefe"], "roles": ["boss", "admin", "supervisor"], "title": "Cómo aprueba el jefe una pieza en rojo", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "0473ec8a-5e97-43b8-85f3-75a653f847c4", "key": "guia:copies", "body": "En la pieza, pestaña Copies: se elige la fórmula (hay 9), la voz (la del jefe o institucional) y el cierre, y salen tres largos: largo (Instagram, TikTok y Facebook), medio (Threads) y corto (X). La plantilla nunca inventa cifras: usa lo que trae la ficha técnica y marca lo que falta. Cambiar un copy de una pieza aprobada la devuelve a revisión.", "tags": ["copies", "formula", "voz", "cierre", "plantilla", "corregir"], "roles": ["social", "admin", "supervisor"], "title": "Cómo se escriben los copies", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "481fa792-fce2-4ccf-9f8e-2b7d6128e24c", "key": "guia:crear-pieza", "body": "«Crear» → Nueva pieza (o desde el material del evento). Se elige el tipo, el título y la categoría, y se sube el video final y la portada. Cada archivo nuevo es una versión: un archivo subido no se reemplaza. Luego se escriben los copies y se manda a aprobar eligiendo verde, amarillo o rojo. Si piden cambios, se corrige y se sube una versión nueva: vuelve sola a revisión.", "tags": ["pieza", "crear", "version"], "roles": ["social", "admin"], "title": "Cómo se crea una pieza", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "96a9ea9b-bcea-48e1-8ce1-0af52a365559", "key": "guia:dictar", "body": "En los campos largos (ficha, storyboard, comentarios) se puede dictar con el micrófono del teclado del teléfono (iPhone o Gboard). Después conviene revisar nombres y cifras antes de guardar.", "tags": ["dictar", "voz", "microfono"], "roles": null, "title": "Dictar en vez de escribir", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "9c6119af-999a-40a0-8f1f-4b027ae510ef", "key": "guia:doble-factor", "body": "El doble factor es obligatorio para el jefe, Despacho, Supervisión y Administración. Sin él la plataforma no muestra la agenda ni deja aprobar. Redes, Grabación y Secretaría entran solo con el código del correo. Si alguien pierde el teléfono, administración le cierra las sesiones (Ajustes → Equipo) y le ayuda a activar el doble factor de nuevo.", "tags": ["doble factor", "seguridad", "autenticador"], "roles": null, "title": "Doble factor", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "80934d7a-d420-41c6-9657-4f05e690f087", "key": "guia:entrar", "body": "Administración te invita con tu correo y tu rol, y te llega un correo de invitación. En «Entrar» escribes tu correo y te llega un código de 6 números: no hay contraseñas. La primera vez, si tu rol lo pide, activas el doble factor con una app autenticadora (por ejemplo Google Authenticator) y desde ahí lo usas al entrar. Si no llega el código: revisa spam y que el correo esté bien escrito; si sigue sin llegar, avisa a administración.", "tags": ["entrar", "codigo", "acceso", "contrasena", "clave"], "roles": null, "title": "Cómo se entra a la plataforma", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "207eb135-17fb-4b2c-8a46-d0e1d0614e32", "key": "guia:ficha-tecnica", "body": "La ficha técnica de un evento lleva: de qué se trata la obra o el acto, quién lo dirige, quién está a cargo, los logros, las cifras clave con su fuente y el protocolo (cómo va el acto). Mientras más completa, mejores copies y storyboard: la plantilla de copies nunca inventa cifras, así que lo que falta en la ficha falta en el copy. En Hoy, Despacho ve las fichas incompletas.", "tags": ["ficha", "evento", "cifras", "llenar"], "roles": ["dispatch", "admin", "secretary", "social", "supervisor"], "title": "Qué lleva la ficha técnica", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "d6549b5a-a6f0-4a58-9240-6cbaeea519ef", "key": "guia:frase-jefe", "body": "Si a una pieza le falta una frase del jefe, Supervisión, Redes o Administración la piden desde la pieza con «Pedir frase al jefe»: se anota el segundo del video y la frase que hace falta. El jefe graba el audio y lo sube; mientras tanto, en Hoy de Redes sale «Esperando frase del jefe».", "tags": ["frase", "jefe", "audio", "voz"], "roles": ["supervisor", "social", "admin", "boss"], "title": "Pedir una frase al jefe", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "817e6fe3-b8b1-4896-ae49-73c6e6dabb76", "key": "guia:invitar", "body": "Ajustes → Equipo: escribir el correo, el nombre y el rol, y tocar Invitar. A la persona le llega un correo con la invitación. En Equipo también se cambian los roles de alguien (se agregan o se quitan), se cierran sus sesiones (por ejemplo si perdió el teléfono) y se desactiva a quien ya no está: así pierde el acceso.", "tags": ["invitar", "equipo", "roles", "acceso", "desactivar", "sesiones"], "roles": ["admin"], "title": "Cómo se invita a alguien", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "5fcc5783-a4b6-4ee6-99c0-b7ebf3cfedcd", "key": "guia:marcar-realizado", "body": "Cuando el evento ya pasó, el jefe, Despacho, Administración o quien lo grabó lo marcan como realizado desde su ficha. Así el material queda en la Biblioteca con su día y Redes ve solo ese día (nunca la hora). No se puede marcar un evento antes de que ocurra.", "tags": ["realizado", "biblioteca", "pasados"], "roles": ["dispatch", "admin", "boss", "camera"], "title": "Marcar un evento como realizado", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "3c56ee72-508e-40fd-b4f3-4b10acadf8bc", "key": "guia:mi-perfil", "body": "En Mi perfil (el menú de tu cuenta, arriba a la derecha) cambias tu nombre, tu número de teléfono, qué avisos te llegan por correo y al teléfono y las horas de silencio; ahí también activas los avisos en este teléfono. El correo con el que entras no se cambia ahí: si hace falta, pídeselo a administración.", "tags": ["perfil", "nombre", "numero", "telefono", "cuenta"], "roles": null, "title": "Mi perfil: nombre, teléfono y avisos", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "2672f5b2-bad2-4092-aeef-bdd740cc4bd2", "key": "guia:modo-lectura", "body": "En la ficha de cada evento está «Lo que voy a decir»: el texto del storyboard en letra grande para leerlo antes del acto, como un apuntador. Lo arma Redes en el storyboard.", "tags": ["lectura", "discurso", "storyboard"], "roles": ["boss", "admin", "social", "dispatch"], "title": "Lo que voy a decir (modo lectura)", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "b7147652-c215-497c-b529-6c7cfbbc21c8", "key": "guia:no-puedo-publicar", "body": "Las causas: la pieza no está aprobada (o volvió a revisión porque cambió el video o un copy), el copy o la portada no son los aprobados, o el video no cumple las reglas de esa red (duración, formato, medidas, peso o largo del copy). La pantalla de Publicar dice en rojo qué falla en cada red.", "tags": ["publicar", "error", "aprobada"], "roles": ["social", "admin"], "title": "Por qué no deja publicar una pieza", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "8cf3afee-8896-4b78-a8b0-4a77e66352e0", "key": "guia:no-tengo-permiso", "body": "Si abres una pantalla que no es de tu rol, la plataforma te devuelve a Hoy. No es una falla: cada rol ve solo lo suyo. Si de verdad la necesitas para tu trabajo, pídeselo a administración.", "tags": ["permisos", "hoy", "no puedo"], "roles": null, "title": "Cuando una pantalla no te deja entrar", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "2b6235ee-8f2f-428a-b28a-d4678f910315", "key": "guia:nuevo-evento", "body": "Para crear o proponer un evento: «Crear» (arriba) → Nuevo evento. Se llenan título, lugar, municipio, de qué se trata, la parte privada (fecha, hora, duración, dirección, cómo llegar, contactos) y la ficha técnica. Despacho y Administración crean eventos; Secretaría los propone y el jefe decide. La parte privada solo la ven el jefe, Despacho, Administración y quien graba.", "tags": ["evento", "crear", "proponer"], "roles": ["dispatch", "admin", "secretary"], "title": "Cómo se crea un evento", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "727e606c-211b-4547-ba58-c4ad0dd58b71", "key": "guia:permisos", "body": "Ver la agenda con fecha y hora: jefe, Despacho y Administración; Grabación solo sus eventos. Crear y editar eventos y fichas: Despacho y Administración (Secretaría propone). Aceptar, rechazar y calificar eventos: solo el jefe. Asignar quién graba: Despacho, Redes y Administración. Armar el storyboard: Redes y Administración (los demás lo leen). Subir material crudo: Redes, Administración y Grabación en sus eventos. Crear piezas, copies y mandar a aprobar: Redes y Administración. Aprobar verdes y amarillas y los tweets: Supervisión. Aprobar rojas: el jefe. Pedir cambios: Supervisión y el jefe. Publicar a mano y cargar métricas: Redes y Administración. Ver resultados: jefe, Redes, Supervisión y Administración. Biblioteca: Despacho, Redes, Supervisión y Administración. Invitar personas, roles y ajustes: Administración.", "tags": ["permisos", "quien puede"], "roles": null, "title": "Tabla de permisos", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "65574628-9142-4dfb-ba98-1fd3cf1e87be", "key": "guia:publicacion-jefe", "body": "En Publicar → «Lo que publicó el jefe»: se anota la red, un título y el link de lo que el jefe subió por su cuenta, para que cuente en Resultados. No pasa por aprobación porque ya salió y la plataforma nunca lo envía.", "tags": ["publicar", "jefe", "espontanea"], "roles": ["social", "admin"], "title": "Registrar lo que el jefe publicó por su cuenta", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "fef33e60-392c-4bc8-b324-d8d1152a6fb1", "key": "guia:publicar", "body": "En Publicar → nueva publicación: se eligen la pieza aprobada y las redes. La plataforma revisa duración, medidas, peso y largo del copy de cada red y muestra las mejores horas. Se descarga el paquete, se publica en la red y se marca «Ya lo publiqué» con el link. Solo se publica lo aprobado, tal cual se aprobó: si cambió el video o un copy, la pieza vuelve a revisión y lo programado vuelve a borrador. La publicación automática está apagada en esta fase.", "tags": ["publicar", "link", "paquete"], "roles": ["social", "admin"], "title": "Cómo se publica a mano", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "dfebe4b3-99d0-4ae1-a89f-9c8ab7b73f9b", "key": "guia:resultados", "body": "En Resultados se cargan las métricas de cada publicación a mano o con el CSV de la red, y se ve «¿A qué hora nos va mejor?»: compara vistas e interacción por red y franja horaria. Con pocos datos lo dice. Nunca interpreta apoyo político. Lo ven el jefe, Redes, Supervisión y Administración.", "tags": ["resultados", "metricas", "csv"], "roles": ["admin", "social", "supervisor", "boss"], "title": "Resultados y métricas", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "3be9afac-e459-4976-b4e2-8dee7730430f", "key": "guia:rol-administracion", "body": "Para qué: manejar el equipo, los permisos y los ajustes. Puede hacer todo lo de Redes, pero nunca aprueba. Inicio: Hoy, con lo de Redes y lo trancado. Menú: Hoy, Agenda, Piezas y «Más» (Por aprobar, Tweets, Publicar, Resultados, Biblioteca, Ajustes). No aprueba piezas ni tweets ni pide cambios con decisión formal (solo comenta), no edita ni borra el registro de cambios y no enciende la publicación automática.", "tags": ["administracion", "rol"], "roles": ["admin"], "title": "Qué hace Administración en la plataforma", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "56cdb185-e9e1-46b0-8f18-8e2459fea722", "key": "guia:rol-despacho", "body": "Para qué: llevar la agenda del jefe y que cada evento tenga su ficha técnica completa, para que Redes y Grabación puedan trabajar. Inicio: Hoy con los eventos del día, fichas incompletas y cuántos esperan la decisión del jefe. Menú: Hoy, Agenda y Biblioteca; «Crear» → Nuevo evento. Puede crear eventos con fecha, hora, duración, dirección, cómo llegar, contactos y ficha técnica (avisa si choca con otro), ver la agenda en calendario (día, semana o mes), cambiar fecha, lugar o ficha, asignar o quitar a quien graba, marcar el evento como realizado y ver y descargar el material. No ve piezas, copies, tweets, publicaciones ni resultados, no sube material ni edita el storyboard, no borra eventos (solo Administración) y no decide por el jefe.", "tags": ["despacho", "rol"], "roles": ["dispatch", "admin"], "title": "Qué hace Despacho en la plataforma", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "d9c17829-61cc-4053-aee7-a0c33b25189b", "key": "guia:rol-grabacion", "body": "Para qué: grabar los eventos asignados y subir el material ordenado. Inicio: Hoy con sus eventos y los pasados sin material («Sube el material»). Menú: Hoy y «Mis eventos». Ve solo los eventos que le asignaron, con su parte privada; lee la ficha y el storyboard para saber qué tomas hacen falta; sube el material crudo; descarga el material de sus eventos y marca el evento como realizado. No ve eventos que no le asignaron, no sube finales ni portadas ni sube a eventos ajenos, no ve piezas, tweets ni publicaciones y no edita ficha, fecha ni storyboard.", "tags": ["grabacion", "rol"], "roles": ["camera", "admin"], "title": "Qué hace Grabación en la plataforma", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "ef75270b-3d0d-4c05-80ec-04f57389d4a6", "key": "guia:rol-jefe", "body": "Inicio: «Te toca aprobar» (piezas en rojo con su reloj) y dos botones, Política y Digital. Menú: Inicio, Agenda, Por aprobar, Resultados y Digital. Puede aprobar las piezas en rojo después de marcar la lista de 4 chequeos, pedir cambios o comentar cualquier pieza anotando el segundo exacto del video, cambiar el nivel de una pieza (incluso sacarla del rojo), calificar cada evento de 1 a 10 y aceptarlo o rechazarlo (Política o la ficha del evento), leer «Lo que voy a decir» en letra grande (modo lectura), ver la agenda completa y marcar un evento como realizado, y ver lo publicado y cómo nos va (Digital y Resultados). No aprueba verdes, amarillas ni tweets (son de supervisión), no crea eventos ni cambia la ficha (es de Despacho) y no sube material, crea piezas ni publica.", "tags": ["jefe", "rol"], "roles": ["boss", "admin"], "title": "Qué hace el jefe en la plataforma", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "ab51e14a-6311-40ee-adc7-c53b4a23d3d2", "key": "guia:rol-redes", "body": "Para qué: convertir cada evento en piezas para las redes: storyboard, video final, copies, aprobación, publicación y resultados. Inicio: Hoy con cambios pedidos, eventos sin storyboard, material que llegó, piezas listas para publicar, días de tweets y lo trancado. Menú: Hoy, Eventos, Piezas, Tweets y «Más» (Publicar, Resultados, Biblioteca). «Crear»: pieza, tweets, publicación. No ve la fecha, la hora ni la dirección de los eventos, no aprueba piezas ni tweets, no publica nada no aprobado (ni con un copy o portada distintos a los aprobados), no baja el nivel de una pieza después de la primera revisión y no reemplaza archivos (se sube una versión nueva).", "tags": ["redes", "rol"], "roles": ["social", "admin"], "title": "Qué hace Redes en la plataforma", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "3c0fa907-74f7-4ef9-b632-9a7870d6a2eb", "key": "guia:rol-secretaria", "body": "Para qué: proponer eventos para que el jefe decida. Inicio: Hoy con sus propuestas y si están esperando, aceptadas o rechazadas. Menú: Hoy y «Mis eventos»; «Crear» → Proponer un evento. Puede proponer un evento con título, lugar, municipio, de qué se trata, la parte privada y la ficha técnica, ver el estado de lo que propuso y ver la ficha y el storyboard de sus propios eventos. No ve eventos de otras personas, no ve la fecha, la hora ni la dirección después de enviar la propuesta (ni siquiera de lo suyo), no asigna quién graba y no ve material, piezas ni tweets. Si hay que corregir algo que propuso, le avisa a Despacho para que lo corrija: Secretaría no tiene botón para cambiar una propuesta ya enviada.", "tags": ["secretaria", "rol", "proponer"], "roles": ["secretary", "admin"], "title": "Qué hace Secretaría en la plataforma", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "ef52c709-02d8-450d-b366-f40d99279d62", "key": "guia:rol-supervision", "body": "Para qué: que nada salga sin revisión. Aprueba las piezas verdes y amarillas y los tweets; en las rojas puede pedir cambios, pero las aprueba el jefe. Inicio: Hoy con piezas por aprobar y su reloj, tweets que esperan y lo vencido. Menú: Hoy, Por aprobar, Resultados y «Más» (Tweets, Biblioteca). No aprueba piezas en rojo ni las saca del rojo, no ve la agenda con fecha y hora, no crea ni edita piezas, copies o publicaciones y no aprueba sin doble factor.", "tags": ["supervision", "rol"], "roles": ["supervisor", "admin"], "title": "Qué hace Supervisión en la plataforma", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "d208e8c9-57aa-4e66-90aa-8b53d3b7822f", "key": "guia:roles", "body": "Jefe: decide los eventos, se prepara para cada acto y aprueba lo sensible (rojo). Despacho: arma la agenda, las fichas técnicas y asigna quién graba. Secretaría: propone eventos. Redes: storyboard, piezas, copies, tweets, publicar y resultados. Supervisión: aprueba piezas verdes y amarillas y los tweets. Grabación: graba y sube el material crudo de sus eventos. Administración: equipo, permisos y ajustes, y puede hacer todo lo de Redes, pero nunca aprueba.", "tags": ["roles", "permisos", "quien"], "roles": null, "title": "Quién hace qué (resumen de roles)", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "89da6a53-88c7-421b-8e9e-d8cabee50023", "key": "guia:semaforo-reglas", "body": "Las piezas verdes y amarillas las aprueba supervisión; las rojas, solo el jefe. Quien manda una pieza a aprobar elige el color: verde si es rutina, amarillo si es lo normal y rojo si es sensible (política, crisis, aclaratorias). Supervisión, el jefe o administración pueden cambiarlo. La falta de respuesta no es aprobación: si no se aprueba a tiempo y vence el plazo, la pieza sigue sin aprobar, sale en «Trancado» y se avisa de nuevo; nunca sale sola. Lo que sale es exactamente lo aprobado: si cambia el video o un copy, vuelve a revisión, y si cambió mientras alguien la revisaba, esa aprobación se rechaza y hay que abrirla de nuevo. Si una pieza aprobada por supervisión se sube a rojo, vuelve a revisión para el jefe. Una pieza en rojo solo baja con el jefe o administración. Lo que el jefe publica por su cuenta no pasa por aprobación (ya salió): Redes lo registra después con su link.", "tags": ["aprobar", "semaforo", "rojo", "amarillo", "verde", "color", "nivel", "plazo", "tiempo", "trancado"], "roles": null, "title": "Reglas del semáforo de aprobación", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "baaeb01f-e00d-4c78-9ea3-1200dcd6c439", "key": "guia:storyboard", "body": "En la ficha del evento, pestaña Storyboard: «Lo que va a decir el jefe» y los bloques, cada uno con plano, ángulo, la frase del jefe, las tomas de apoyo y un dato con su fuente. Lo arman Redes y Administración; el resto lo lee. Conviene armarlo para los eventos que el jefe ya aceptó.", "tags": ["storyboard", "evento", "tomas", "planos"], "roles": ["social", "admin", "camera", "dispatch", "boss"], "title": "Cómo se arma el storyboard", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "9d30b9bd-a5ba-468d-a65f-86d0a2715855", "key": "guia:subir-material", "body": "Abrir el evento (Mis eventos o Agenda), pestaña Material, y subir cada archivo en su casilla: jefe hablando, dron, tomas de apoyo u otros. Si se va la señal o el internet, la subida sigue sola al volver. Un archivo subido no se reemplaza: si hubo un error, se sube el correcto y se avisa a Redes; quitar el equivocado lo hace administración. Después, marcar el evento como realizado.", "tags": ["material", "subir", "señal", "videos", "fotos", "internet", "conexion"], "roles": ["camera", "social", "admin"], "title": "Cómo se sube el material crudo", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "c76b60ef-1771-4da1-af3b-e78ca79dccc7", "key": "guia:telefono", "body": "Abajo están las opciones principales y «Más» con el resto. Arriba: buscar, la campana de avisos, «Crear» (según tu rol) y tu cuenta. Para usarla como app: en el navegador del teléfono, «Agregar a la pantalla de inicio». En iPhone los avisos al teléfono solo llegan con la app agregada a la pantalla de inicio. Los avisos se activan en Mi perfil.", "tags": ["telefono", "instalar", "app", "avisos"], "roles": null, "title": "La plataforma en el teléfono", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_knowledge (id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at) select id, roles, title, body, tags, origin, key, active, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_knowledge, '{"id": "be946215-fda3-48d8-9274-e7de81915ff2", "key": "guia:tweets-semana", "body": "En Tweets → nueva tanda: se pega o se sube el documento de la semana, la plataforma separa los tweets, marca repetidos y largos y los reparte 2 o 3 por día en las franjas guardadas. Supervisión los aprueba; ya aprobados, Redes los programa. Cuando quedan pocos días de tweets programados, la plataforma avisa a Redes. Para mover un tweet, se toca y se cambia día y hora (arrastrar no funciona con el dedo).", "tags": ["tweets", "semana", "tanda"], "roles": ["social", "admin", "supervisor"], "title": "Tweets de la semana", "active": true, "origin": "plataforma", "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "updated_at": "2026-10-26T07:40:36.406253+00:00"}'::jsonb);
insert into public.assistant_scripts (id, roles, topic, triggers, script, notes, always, active, origin, key, times_used, last_used_at, created_by, created_at, updated_at) select id, roles, topic, triggers, script, notes, always, active, origin, key, times_used, last_used_at, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_scripts, E'{"id": "008c92a6-7383-4ce0-b929-fbe54ad2b5eb", "key": "fabrica:estado-pieza", "notes": "Si salen varias, pregunta cuál; no elige. Lo que no devuelve la herramienta no existe para el asistente.", "roles": ["admin", "social", "supervisor", "boss"], "topic": "Cómo va una pieza", "active": true, "always": false, "origin": "fabrica", "script": "Persona: como va la pieza de la cancha?\\n[ASISTENTE]: Déjame ver. [usa estado_pieza] La pieza «[titulo]» está [estado]. ¿Quieres abrirla?\\n[ASISTENTE]: «[titulo]» va en [estado]. Si necesitas que avance, revisa quién la aprueba según su color.\\nSi hay varias → [ASISTENTE]: Encontré varias: [lista]. ¿Cuál de ellas?\\nSi no la encuentra → [ASISTENTE]: No encontré ninguna pieza con ese nombre. ¿Me das otra palabra del título?", "triggers": ["como va la pieza", "estado de la pieza", "como va el video", "ya aprobaron", "la aprobaron", "esta aprobada", "pieza", "en que va"], "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "times_used": 0, "updated_at": "2026-10-26T07:40:36.406253+00:00", "last_used_at": null}'::jsonb);
insert into public.assistant_scripts (id, roles, topic, triggers, script, notes, always, active, origin, key, times_used, last_used_at, created_by, created_at, updated_at) select id, roles, topic, triggers, script, notes, always, active, origin, key, times_used, last_used_at, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_scripts, E'{"id": "013dbb31-ecc6-430e-a417-0cb2e5ec58c2", "key": "fabrica:algo-falla", "notes": "No inventa la causa. Pregunta qué pasó y avisa si la persona quiere.", "roles": null, "topic": "Algo no funciona o una queja", "active": true, "always": false, "origin": "fabrica", "script": "Persona: no me carga la pantalla de piezas\\n[ASISTENTE]: Qué fastidio. Prueba recargar la página; si sigue igual, le aviso a administración con lo que me cuentas. ¿Le aviso?\\n[ASISTENTE]: Lo siento. ¿Qué estabas haciendo cuando falló? Con eso le aviso a administración para que lo revisen.\\nSi dice «sí, avisa» → [ASISTENTE]: Listo, ya le avisé a administración con esta conversación. [usa avisar_al_equipo]\\nSi dice «no me llega el código» → [ASISTENTE]: Revisa la carpeta de spam y que el correo esté bien escrito. Si en unos minutos no llega, le aviso a administración.", "triggers": ["no funciona", "no sirve", "da error", "sale un error", "se trabo", "no carga", "no puedo entrar", "falla", "me quejo", "queja"], "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "times_used": 0, "updated_at": "2026-10-26T07:40:36.406253+00:00", "last_used_at": null}'::jsonb);
insert into public.assistant_scripts (id, roles, topic, triggers, script, notes, always, active, origin, key, times_used, last_used_at, created_by, created_at, updated_at) select id, roles, topic, triggers, script, notes, always, active, origin, key, times_used, last_used_at, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_scripts, E'{"id": "0bb46038-5339-4e45-838f-531c6746c310", "key": "fabrica:dictar", "notes": "Es el dictado del teclado del teléfono; la plataforma no graba nada.", "roles": null, "topic": "Dictar por voz", "active": true, "always": false, "origin": "fabrica", "script": "Persona: puedo dictar en vez de escribir?\\n[ASISTENTE]: Sí: en cualquier campo largo toca el micrófono del teclado del teléfono y habla. Después revisa lo que escribió.\\n[ASISTENTE]: Claro, usa el micrófono del teclado. Ojo con nombres y cifras: revísalos antes de guardar.", "triggers": ["dictar", "microfono", "hablar en vez de escribir", "por voz", "nota de voz"], "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "times_used": 0, "updated_at": "2026-10-26T07:40:36.406253+00:00", "last_used_at": null}'::jsonb);
insert into public.assistant_scripts (id, roles, topic, triggers, script, notes, always, active, origin, key, times_used, last_used_at, created_by, created_at, updated_at) select id, roles, topic, triggers, script, notes, always, active, origin, key, times_used, last_used_at, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_scripts, E'{"id": "0f668f37-ff9b-46cf-9812-ce6ddea0fe5d", "key": "fabrica:mandar-aprobar", "notes": "Los plazos de cada color salen de la ficha del semáforo; no se inventan.", "roles": ["admin", "social", "supervisor", "boss"], "topic": "Mandar a aprobar y el semáforo", "active": true, "always": false, "origin": "fabrica", "script": "Persona: que color le pongo a la pieza?\\n[ASISTENTE]: Verde si es rutina, amarillo si es lo normal y rojo si es sensible (política, crisis o aclaratorias). El rojo solo lo aprueba [JEFE].\\n[ASISTENTE]: Depende de lo delicada: verde y amarillo los aprueba supervisión; rojo, [JEFE]. Si dudas, amarillo.\\nSi dice «¿y si nadie responde?» → [ASISTENTE]: La falta de respuesta no es aprobación: la pieza sigue sin salir y la plataforma avisa de nuevo.", "triggers": ["mandar a aprobar", "enviar a aprobar", "semaforo", "que color", "verde", "amarillo", "rojo", "nivel de la pieza"], "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "times_used": 0, "updated_at": "2026-10-26T07:40:36.406253+00:00", "last_used_at": null}'::jsonb);
insert into public.assistant_scripts (id, roles, topic, triggers, script, notes, always, active, origin, key, times_used, last_used_at, created_by, created_at, updated_at) select id, roles, topic, triggers, script, notes, always, active, origin, key, times_used, last_used_at, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_scripts, E'{"id": "0f8f40fb-bc09-466e-a726-5b931d1ef24c", "key": "fabrica:eres-bot", "notes": "No discute ni finge ser una persona. Ofrece avisar a alguien.", "roles": null, "topic": "¿Eres un bot?", "active": true, "always": false, "origin": "fabrica", "script": "Persona: eres un bot?\\n[ASISTENTE]: Soy [ASISTENTE], el asistente de la plataforma: no soy una persona del equipo, pero lo que te digo sale de lo que el equipo me enseñó. ¿En qué te ayudo?\\n[ASISTENTE]: Soy el asistente de [APP], no una persona. Si prefieres hablar con alguien del equipo, le aviso ahora mismo.\\nSi dice «quiero una persona» → [ASISTENTE]: Listo, ya le avisé a administración y te escriben por aquí. [usa avisar_al_equipo]", "triggers": ["eres un bot", "eres un robot", "eres una ia", "eres inteligencia artificial", "eres real", "eres humano", "eres una persona", "eres una maquina"], "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "times_used": 0, "updated_at": "2026-10-26T07:40:36.406253+00:00", "last_used_at": null}'::jsonb);
insert into public.assistant_scripts (id, roles, topic, triggers, script, notes, always, active, origin, key, times_used, last_used_at, created_by, created_at, updated_at) select id, roles, topic, triggers, script, notes, always, active, origin, key, times_used, last_used_at, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_scripts, E'{"id": "24f7167e-166f-447d-a983-bfb320301c6d", "key": "fabrica:avisos-telefono", "notes": "Los avisos nunca llevan fecha, hora ni lugar de un evento.", "roles": null, "topic": "Avisos al teléfono e instalar la app", "active": true, "always": false, "origin": "fabrica", "script": "Persona: como instalo la app?\\n[ASISTENTE]: En el teléfono abre la plataforma en el navegador y toca «Agregar a la pantalla de inicio». Después activa los avisos desde Mi perfil.\\n[ASISTENTE]: Agrégala a la pantalla de inicio desde el menú del navegador y queda como una app. En iPhone los avisos solo llegan así.", "triggers": ["instalar la app", "pantalla de inicio", "avisos al telefono", "activar avisos", "notificaciones", "como instalo"], "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "times_used": 0, "updated_at": "2026-10-26T07:40:36.406253+00:00", "last_used_at": null}'::jsonb);
insert into public.assistant_scripts (id, roles, topic, triggers, script, notes, always, active, origin, key, times_used, last_used_at, created_by, created_at, updated_at) select id, roles, topic, triggers, script, notes, always, active, origin, key, times_used, last_used_at, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_scripts, E'{"id": "33fd385c-3372-4e07-b8a6-3d9b6d20a004", "key": "fabrica:copies", "notes": "Las fórmulas activas salen de sus fichas automáticas.", "roles": ["admin", "social", "supervisor"], "topic": "Copies: fórmula, voz y cierre", "active": true, "always": false, "origin": "fabrica", "script": "Persona: como hago los copies?\\n[ASISTENTE]: En la pieza, pestaña Copies: eliges la fórmula, la voz ([JEFE] o institucional) y el cierre, y salen los tres largos. La plantilla nunca inventa cifras.\\n[ASISTENTE]: Los copies salen de la ficha técnica con la fórmula que elijas. Si falta un dato, te lo marca para que lo completes.\\nSi dice «¿qué fórmula uso?» → [ASISTENTE]: Depende de la pieza; te digo de qué va cada una si quieres.", "triggers": ["copies", "copy", "formula", "formulas", "voz del jefe", "institucional", "cierre", "hashtags"], "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "times_used": 0, "updated_at": "2026-10-26T07:40:36.406253+00:00", "last_used_at": null}'::jsonb);
insert into public.assistant_scripts (id, roles, topic, triggers, script, notes, always, active, origin, key, times_used, last_used_at, created_by, created_at, updated_at) select id, roles, topic, triggers, script, notes, always, active, origin, key, times_used, last_used_at, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_scripts, E'{"id": "36908d19-05ae-49ce-8b0b-1c938dca2228", "key": "fabrica:asignar-grabacion", "notes": "Asignan Despacho, Redes y administración.", "roles": ["admin", "dispatch", "social"], "topic": "Asignar quién graba", "active": true, "always": false, "origin": "fabrica", "script": "Persona: como asigno a quien graba?\\n[ASISTENTE]: En la ficha del evento, en la parte de quién graba, eliges a la persona. Le llega un aviso al momento.\\n[ASISTENTE]: Abre el evento y asigna a quien graba; si hay que cambiarlo, lo quitas y pones a otra persona.", "triggers": ["asignar", "quien graba", "asignar camarografo", "asignar grabacion", "quitar a quien graba"], "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "times_used": 0, "updated_at": "2026-10-26T07:40:36.406253+00:00", "last_used_at": null}'::jsonb);
insert into public.assistant_scripts (id, roles, topic, triggers, script, notes, always, active, origin, key, times_used, last_used_at, created_by, created_at, updated_at) select id, roles, topic, triggers, script, notes, always, active, origin, key, times_used, last_used_at, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_scripts, E'{"id": "3e8b76fd-d921-40e1-b335-58542be593f3", "key": "fabrica:buscar-evento", "notes": "Con buscar_evento: da el estado, nunca la fecha, la hora ni el lugar.", "roles": null, "topic": "Cómo va un evento", "active": true, "always": false, "origin": "fabrica", "script": "Persona: como va el evento de la escuela?\\n[ASISTENTE]: Ya lo busco. [usa buscar_evento] El evento «[titulo]» está en [estado]. ¿Quieres abrir su ficha?\\n[ASISTENTE]: «[titulo]»: [estado]. Desde su ficha ves el storyboard y el material.\\nSi hay varios → [ASISTENTE]: Encontré varios: [lista]. ¿Cuál es?", "triggers": ["como va el evento", "estado del evento", "el evento de", "storyboard del evento", "ficha del evento", "evento", "acto"], "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "times_used": 0, "updated_at": "2026-10-26T07:40:36.406253+00:00", "last_used_at": null}'::jsonb);
insert into public.assistant_scripts (id, roles, topic, triggers, script, notes, always, active, origin, key, times_used, last_used_at, created_by, created_at, updated_at) select id, roles, topic, triggers, script, notes, always, active, origin, key, times_used, last_used_at, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_scripts, E'{"id": "484d3c38-5bd3-41f1-a6dd-cd14ae0c037e", "key": "fabrica:mejores-horas", "notes": "Con mejores_horas. Las horas salen de lo medido por el equipo, no se inventan.", "roles": null, "topic": "Mejores horas para publicar", "active": true, "always": false, "origin": "fabrica", "script": "Persona: a que hora publico en tiktok?\\n[ASISTENTE]: [usa mejores_horas] En TikTok rinde más [horas]. Es un consejo: nunca bloquea la publicación.\\n[ASISTENTE]: Para esa red lo mejor es [horas]. Si no te da, publica igual: el horario es una guía.\\nSi no dice la red → [ASISTENTE]: ¿Para qué red? Te digo las mejores horas de cada una.", "triggers": ["a que hora publico", "mejor hora", "mejores horas", "a que hora nos va mejor", "cuando publico", "horario para publicar", "que dia publico"], "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "times_used": 0, "updated_at": "2026-10-26T07:40:36.406253+00:00", "last_used_at": null}'::jsonb);
insert into public.assistant_scripts (id, roles, topic, triggers, script, notes, always, active, origin, key, times_used, last_used_at, created_by, created_at, updated_at) select id, roles, topic, triggers, script, notes, always, active, origin, key, times_used, last_used_at, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_scripts, E'{"id": "5021f80d-ec11-44fb-bf94-18725d6795ca", "key": "fabrica:subir-material", "notes": "Grabación sube solo a sus eventos asignados; finales y portadas los sube Redes.", "roles": ["admin", "social", "camera"], "topic": "Cómo se sube el material", "active": true, "always": false, "origin": "fabrica", "script": "Persona: como subo el material?\\n[ASISTENTE]: Abre el evento en Mis eventos, ve a Material y sube cada archivo en su casilla: jefe hablando, dron, apoyo u otros. ¿Ya tienes el evento abierto?\\n[ASISTENTE]: En la ficha del evento, pestaña Material: tocas la casilla que corresponde y eliges los archivos. Si se va la señal, la subida sigue sola al volver.\\nSi dice «me equivoqué de archivo» → [ASISTENTE]: Un archivo subido no se reemplaza: sube el correcto y avísale a Redes cuál vale. Si hay que quitar el otro, lo hace administración.", "triggers": ["subir material", "subir el material", "como subo", "subir video", "material crudo", "se fue la señal", "se corto la subida"], "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "times_used": 0, "updated_at": "2026-10-26T07:40:36.406253+00:00", "last_used_at": null}'::jsonb);
insert into public.assistant_scripts (id, roles, topic, triggers, script, notes, always, active, origin, key, times_used, last_used_at, created_by, created_at, updated_at) select id, roles, topic, triggers, script, notes, always, active, origin, key, times_used, last_used_at, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_scripts, E'{"id": "50e50338-1ad6-459f-adc8-cb520169d4b6", "key": "fabrica:entrar", "notes": "Nunca pide el código ni claves.", "roles": null, "topic": "Entrar, código y doble factor", "active": true, "always": false, "origin": "fabrica", "script": "Persona: no me llega el codigo\\n[ASISTENTE]: Revisa spam y que el correo esté bien escrito; el código es de 6 números y llega en uno o dos minutos. Si no aparece, le aviso a administración.\\n[ASISTENTE]: Para entrar escribes tu correo y te llega un código; algunos roles además usan el autenticador. ¿En qué paso te quedaste?\\nSi dice «perdí el teléfono» → [ASISTENTE]: Avísale ya a administración para que cierre tus sesiones y te ayude con el doble factor. ¿Le aviso yo?", "triggers": ["codigo", "no me llega el codigo", "doble factor", "autenticador", "como entro", "cerrar sesion", "perdi el telefono"], "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "times_used": 0, "updated_at": "2026-10-26T07:40:36.406253+00:00", "last_used_at": null}'::jsonb);
insert into public.assistant_scripts (id, roles, topic, triggers, script, notes, always, active, origin, key, times_used, last_used_at, created_by, created_at, updated_at) select id, roles, topic, triggers, script, notes, always, active, origin, key, times_used, last_used_at, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_scripts, E'{"id": "5534f3e0-0650-434a-a949-144162971172", "key": "fabrica:nuevo-evento", "notes": "La fecha, la hora y la dirección se escriben a mano en el formulario; el asistente nunca las pide ni las repite.", "roles": ["admin", "dispatch", "secretary"], "topic": "Nuevo evento y ficha técnica", "active": true, "always": false, "origin": "fabrica", "script": "Persona: como cargo un evento nuevo?\\n[ASISTENTE]: Toca «Crear» → Nuevo evento, llena los datos y la ficha técnica (quién dirige, logros, cifras con su fuente y protocolo) y guarda.\\n[ASISTENTE]: Desde «Crear» arriba → Nuevo evento. Mientras más completa la ficha, mejor trabajan Redes y Grabación.\\nSi dice «me equivoqué en la propuesta» → [ASISTENTE]: Avísale a Despacho para que la corrija; desde Secretaría no hay botón para cambiarla.", "triggers": ["nuevo evento", "crear un evento", "proponer un evento", "ficha tecnica", "completar la ficha", "cargar un evento"], "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "times_used": 0, "updated_at": "2026-10-26T07:40:36.406253+00:00", "last_used_at": null}'::jsonb);
