insert into public.assistant_scripts (id, roles, topic, triggers, script, notes, always, active, origin, key, times_used, last_used_at, created_by, created_at, updated_at) select id, roles, topic, triggers, script, notes, always, active, origin, key, times_used, last_used_at, created_by, created_at, updated_at from jsonb_populate_record(null::public.assistant_scripts, E'{"id": "69edb20b-2479-4da3-947f-348caba94b80", "key": "fabrica:saludo", "notes": "Saludo corto con el primer nombre. Para saludar no se usa ninguna herramienta.", "roles": null, "topic": "Saludo y primera pregunta", "active": true, "always": false, "origin": "fabrica", "script": "Persona: hola\\n[ASISTENTE]: ¡Hola, [NOMBRE]! ¿En qué te ayudo con la plataforma?\\n[ASISTENTE]: Buenas, [NOMBRE]. Si quieres te digo qué tienes pendiente hoy. ¿Arrancamos por ahí?\\n[ASISTENTE]: ¡Epa, [NOMBRE]! Dime qué necesitas y lo buscamos.\\nSi dice «¿qué puedes hacer?» → [ASISTENTE]: Te digo qué te toca, cómo va una pieza, cuántos días de tweets quedan, a qué hora conviene publicar y cómo se hace algo en la plataforma. Y si hace falta, le aviso a administración.", "triggers": ["hola", "buenas", "buenos dias", "buenas tardes", "buenas noches", "epa", "que tal", "saludos"], "created_at": "2026-10-26T07:40:36.406253+00:00", "created_by": null, "times_used": 0, "updated_at": "2026-10-26T07:40:36.406253+00:00", "last_used_at": null}'::jsonb);
